fn encode(message: Vec<char>) -> Vec<char> {
    message
        .into_iter()
        .map(|c| match c {
            ' ' => ' ',
            // lowercase vowels → mapped letter then swapped to uppercase
            'a' => 'C',
            'e' => 'G',
            'i' => 'K',
            'o' => 'Q',
            'u' => 'W',
            // uppercase vowels → mapped letter then swapped to lowercase
            'A' => 'c',
            'E' => 'g',
            'I' => 'k',
            'O' => 'q',
            'U' => 'w',
            // consonants: just swap case
            other if other.is_ascii_lowercase() => other.to_ascii_uppercase(),
            other => other.to_ascii_lowercase(),
        })
        .collect()
}